function decorateMarkdown(container){for(const pre of container.querySelectorAll('pre')){if(pre.parentElement.classList.contains('code-block'))continue;const code=pre.querySelector('code'),wrapper=document.createElement('div');wrapper.className='code-block';pre.before(wrapper);wrapper.append(pre);const language=code?.className.replace('language-','')||'Code';const tools=document.createElement('div');tools.className='code-tools';const label=document.createElement('span');label.textContent=language;const copy=document.createElement('button');copy.type='button';copy.className='button';copy.title='Copy code';copy.innerHTML=icon('copy')+'Copy';copy.onclick=async()=>{try{await navigator.clipboard.writeText(code?.textContent||pre.textContent);toast('Code copied')}catch{toast('Clipboard unavailable in this browser')}};tools.append(label,copy);wrapper.prepend(tools)}for(const table of container.querySelectorAll('table')){if(table.parentElement.classList.contains('table-scroll'))continue;const wrapper=document.createElement('div');wrapper.className='table-scroll';wrapper.tabIndex=0;wrapper.setAttribute('role','region');wrapper.setAttribute('aria-label','Markdown table');table.before(wrapper);wrapper.append(table)}}
