function leaveReader(clearRoute=true){const focusId=history.state?.returnContext?.focusId||returnContext?.focusId;const scrollTop=history.state?.returnContext?.scrollTop??returnContext?.scrollTop??0;saveReply();currentRelay=null;standalone=false;document.body.classList.remove('reading','standalone');$('reader').hidden=true;$('reader').replaceChildren();$('inbox-view').hidden=false;document.title='Relai — Inbox';if(clearRoute&&route())history.replaceState(null,'',location.pathname+location.search);renderInbox();$('view-content').scrollTop=scrollTop;document.querySelector(`[data-record="${focusId}"] .open-relai`)?.focus({preventScroll:true});renderSidebar()}
