function init(){restoreListRoute();persist();renderSidebar();renderInbox();applyTheme();$('search').oninput=()=>{if(currentRelay)leaveReader();renderInbox()};$('theme-toggle').onclick=()=>{prefs.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';persist();applyTheme()};$('settings-button').onclick=()=>openSettings();$('help-button').onclick=()=>openInfo('help');$('compose-button').onclick=$('mobile-compose').onclick=()=>openCompose();$('menu-button').onclick=()=>{document.body.classList.toggle('sidebar-hidden');toast('Sidebar '+(document.body.classList.contains('sidebar-hidden')?'hidden':'shown'))};$('refresh-button').onclick=()=>toast('Sample data is up to date.');$('select-all').onchange=event=>{document.querySelectorAll('[data-select-record]').forEach(input=>{input.checked=event.target.checked;event.target.checked?selectedRows.add(input.dataset.selectRecord):selectedRows.delete(input.dataset.selectRecord);input.closest('.relai-row').classList.toggle('selected-row',event.target.checked)});paintBulk()};$('tools-toggle').onclick=()=>{prefs.toolsOpen=!prefs.toolsOpen;persist();applyTheme()};$('search-filters').onclick=()=>openChoices($('search-filters'),[{value:'agent',label:'Filter by agent'},{value:'terminal',label:'Filter by terminal'},{value:'clear',label:'Clear filters'}],value=>{if(value==='clear')clearFilters();else $(value==='agent'?'agent-filter':'terminal-filter').click()},{title:'Search filters'});$('more-button').onclick=()=>openChoices($('more-button'),[{value:'clear',label:'Clear all filters',icon:'sliders-horizontal'},{value:'settings',label:'Workspace settings',icon:'settings'}],value=>{if(value==='settings')openSettings();else{clearFilters()}},{title:'Inbox actions'});$('unread-filter').onclick=()=>{unread=!unread;renderInbox()};$('agent-filter').onclick=()=>openChoices($('agent-filter'),[{value:'',label:'All agents',selected:!agentFilter},...agents.map(a=>({value:a.name,label:a.name,class:a.class,selected:agentFilter===a.name,html:`<div class="option-copy">${agentBadge(a.name)}<small>${sessions.filter(s=>s.agent===a.name).length} native sessions</small></div>`}))],value=>{agentFilter=value;renderInbox();renderSidebar()},{title:'Filter by agent',width:225});$('terminal-filter').onclick=()=>openChoices($('terminal-filter'),[{value:'',label:'Any terminal',detail:'All activity states',selected:!terminalFilter},...['running','idle','closed','unknown'].map(state=>({value:state,label:state,detail:{running:'Terminal process is running',idle:'Open and waiting for input',closed:'Resume this session when sending',unknown:'Activity has not been confirmed'}[state],selected:terminalFilter===state,html:`<div class="option-copy">${terminal(state)}<small>${{running:'Terminal process is running',idle:'Open and waiting for input',closed:'Resume this session when sending',unknown:'Activity has not been confirmed'}[state]}</small></div>`}))],value=>{terminalFilter=value;renderInbox()},{title:'Terminal activity',width:250});$('sort-filter').onclick=()=>openChoices($('sort-filter'),[{value:'recent',label:'Most recent',detail:'Latest activity first',selected:sort==='recent',icon:'clock'},{value:'agent',label:'By agent',detail:'Group the list by coding agent',selected:sort==='agent',icon:'messages-square'},{value:'project',label:'By project',detail:'Keep repository context together',selected:sort==='project',icon:'folder'}],value=>{sort=value;renderInbox()},{title:'Sort conversations',width:235});$('mobile-mailbox').onclick=()=>openChoices($('mobile-mailbox'),Object.keys(mailboxTitles).map(name=>({value:name,label:name,selected:view===name,icon:mailboxIcons[name]})),navigateMailbox,{title:'Mailboxes'});
$('cancel-compose').title='Close and keep this draft';stampTooltips(document);$('close-compose').onclick=$('cancel-compose').onclick=()=>{saveComposer();closeModal($('compose'))};$('minimize-compose').onclick=minimizeComposer;$('maximize-compose').onclick=expandComposer;$('send-compose').onclick=submitCompose;$('restore-compose').onclick=()=>openCompose(activeDraftId);$('dismiss-dock').onclick=()=>{$('composer-dock').hidden=true;$('compose-button').focus()};$('compose').addEventListener('cancel',()=>saveComposer());$('compose').addEventListener('close',()=>{closeChoices();saveComposer()});$('compose').addEventListener('keydown',event=>{if(event.altKey&&event.key==='Enter'){event.preventDefault();expandComposer()}if((event.ctrlKey||event.metaKey)&&event.shiftKey&&event.key.toLowerCase()==='m'){event.preventDefault();minimizeComposer()}});$('use-folder').onclick=useFolder;document.querySelectorAll('[data-close-dialog]').forEach(button=>button.onclick=()=>closeModal($(button.dataset.closeDialog)));document.querySelectorAll('[data-info]').forEach(button=>button.onclick=()=>openInfo(button.dataset.info));document.querySelectorAll('.modal').forEach(dialog=>{focusTrap(dialog);dialog.addEventListener('cancel',()=>closeChoices());dialog.addEventListener('close',()=>{closeChoices();if(document.contains(dialog._opener))dialog._opener.focus()})});document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();if(currentRelay)leaveReader();$('search').focus()}if(document.querySelector('dialog[open]')||choiceState)return;const typing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);if(currentRelay&&!typing&&event.key.toLowerCase()==='r'&&!event.ctrlKey&&!event.metaKey){event.preventDefault();toggleReply(true)}if(currentRelay&&!typing&&event.key==='Escape'){event.preventDefault();closeReader()}});const initial=route();if(initial)openRelay(initial.id,{historyUpdate:false,windowOnly:initial.standalone})}
init();

function returnLabel(){return returnContext?.scope!==null&&returnContext?.scope!==undefined?'Back to session':'Back to '+(returnContext?.view||'Inbox')}
function clearHighlights(container){for(const mark of container.querySelectorAll('mark'))mark.replaceWith(document.createTextNode(mark.textContent));container.normalize()}
function highlightText(container,query){const walker=document.createTreeWalker(container,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode())if(!walker.currentNode.parentElement.closest('button'))nodes.push(walker.currentNode);for(const node of nodes){const text=node.textContent,lower=text.toLowerCase(),needle=query.toLowerCase();let position=0,index=lower.indexOf(needle);if(index<0)continue;const fragment=document.createDocumentFragment();while(index>=0){fragment.append(document.createTextNode(text.slice(position,index)));const mark=document.createElement('mark');mark.textContent=text.slice(index,index+query.length);fragment.append(mark);position=index+query.length;index=lower.indexOf(needle,position)}fragment.append(document.createTextNode(text.slice(position)));node.replaceWith(fragment)}}
function sharedFolderLabel(session){const shared=sessions.filter(s=>s.path===session.path).length;return session.worktree?'<span class="tag">Worktree: '+esc(session.worktree)+'</span>':shared>1?'<span class="tag">Shared folder · '+shared+' sessions</span>':''}
function gitDetails(session){if(!session.branch)return `<h3>No Git repository</h3><p><code>${esc(session.path)}</code></p><p>This archived example is a local folder. Git controls become available when the working folder is a repository.</p>`;const files=session.repo==='website'?['src/navigation.css','src/header.tsx']:session.repo==='api'?['auth/refresh.ts','auth/refresh.test.ts']:['Sidebar.tsx','workspace.css'];return `<h3>${esc(session.repo)} · ${esc(session.branch)}</h3><p><code>${esc(session.path)}</code></p>${sharedFolderLabel(session)}<p>Working tree: <strong>2 changed files · +62 −28</strong></p><ul><li>${esc(files[0])} · +24 −12</li><li>${esc(files[1])} · +38 −16</li></ul><blockquote>Changes belong to this working folder. They may include edits from other sessions.</blockquote><p>Last checked: ${esc(session.updated)} · sample snapshot</p><p class="muted">Local Git context preview. No repository operation is performed.</p>`}
function stampTooltips(container){for(const button of container.querySelectorAll('button'))if(!button.title&&button.getAttribute('aria-label'))button.title=button.getAttribute('aria-label')}

function paintGitExamples(session){const group=document.createElement('details');group.className='git-examples';group.innerHTML='<summary>Explore example Git states</summary><p class="muted">Illustrative states of the working folder.</p><div class="git-state-buttons"></div><div id="git-state-example" class="state-banner" hidden></div>';const states={detached:{label:'Detached HEAD',title:'Detached HEAD · a1b2c3d',text:'This folder is at a commit rather than a named branch. The current commit remains visible before sending.'},changed:{label:'Branch changed',title:'Branch changed since the session started',text:'The folder is now on main. This session began on '+(session.branch||'feature/navigation')+'. Recheck the destination before continuing.'},conflict:{label:'Conflict',title:'1 unresolved conflict',text:'workspace.css contains a merge conflict. Review the working folder before asking the agent to continue.'},stale:{label:'Out of date',title:'Git snapshot is out of date',text:'Last checked yesterday. Show a stale indicator until the local service confirms the branch and changes.'}};for(const [key,state] of Object.entries(states)){const button=document.createElement('button');button.className='button';button.textContent=state.label;button.setAttribute('aria-pressed','false');button.onclick=()=>{group.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',b===button));const output=group.querySelector('#git-state-example');output.hidden=false;output.replaceChildren();const strong=document.createElement('strong');strong.textContent=state.title;const text=document.createElement('span');text.textContent=state.text;output.append(strong,text)};group.querySelector('.git-state-buttons').append(button)}$('info-body').append(group)}
